#include <bits/stdc++.h>
using namespace std;const int M=998244353;
int main(){int t;scanf("%d",&t);int MX=3000;vector<vector<int>>dv(MX+1);for(int d=1;d<=MX;d++)for(int k=d;k<=MX;k+=d)dv[k].push_back(d);
 while(t--){int n,m;scanf("%d %d",&n,&m);vector<int>a(n);for(auto&x:a)scanf("%d",&x);
  if(a[0]!=0&&a[0]!=1){puts("0");continue;}
  vector<int>dp(m+1,0),nd(m+1);dp[1]=1;
  for(int i=1;i<n;i++){fill(nd.begin(),nd.end(),0);
   for(int v=1;v<=m;v++){if(!dp[v])continue;for(int d:dv[v]){int w=v+d;if(w>m)break;if(a[i]&&a[i]!=w)continue;nd[w]=(nd[w]+dp[v])%M;}}
   swap(dp,nd);}
  long long s=0;for(int v=1;v<=m;v++)s+=dp[v];printf("%lld\n",s%M);}}
